def chunk_windows(items, size, overlap):
    if size <= 0 or not (0 <= overlap < size):
        raise ValueError("invalid")
    step = size - overlap
    result = []
    for i in range(0, len(items), step):
        result.append(items[i:i+size])
    return result

def chunk_windows(items, size, overlap):
    if size <= 0 or overlap < 0 or overlap >= size:
        raise ValueError("invalid")
    step = size - overlap
    windows = []
    for start in range(0, len(items), step):
        if start >= len(items):
            break
        windows.append(items[start:start + size])
    return windows

def select_latest(records):
    out = {}
    for record in records:
        out.setdefault(record["key"], []).append(record)

    result = {}
    for key in sorted(out):
        group = out[key]
        best = group[0]
        for record in group[1:]:
            if record["revision"] < 0 or record["observed"] < 0:
                raise ValueError("negative revision or observed")
            if (record["revision"], record["observed"]) > (
                best["revision"],
                best["observed"],
            ) or (
                record["revision"] == best["revision"]
                and record["observed"] == best["observed"]
            ):
                best = record
        if best["revision"] < 0 or best["observed"] < 0:
            raise ValueError("negative revision or observed")
        result[key] = dict(best)
    return [result[key] for key in sorted(result)]

def select_latest(records):
    out = {}
    for index, record in enumerate(records):
        key = record["key"]
        revision = record.get("revision")
        observed = record.get("observed")
        if revision is None or observed is None:
            raise ValueError("record missing revision or observed")
        if revision < 0 or observed < 0:
            raise ValueError("revision and observed must be non-negative")
        value = record.get("value")
        current = out.get(key)
        if current is None:
            out[key] = (revision, observed, index, value)
        else:
            prev_rev, prev_obs, prev_index, prev_value = current
            if revision > prev_rev or (revision == prev_rev and observed > prev_obs):
                out[key] = (revision, observed, index, value)
            elif revision == prev_rev and observed == prev_obs:
                out[key] = (revision, observed, index, value)  # last occurrence wins
    result = {}
    for key in sorted(out):
        rev, obs, idx, value = out[key]
        result[key] = {"key": key, "revision": rev, "observed": obs, "value": value}
    return [result[key] for key in sorted(result)]

def select_latest(records):
    out = {}
    for record in records:
        if record["revision"] < 0 or record["observed"] < 0:
            raise ValueError
        key = record["key"]
        if key not in out:
            out[key] = record
        else:
            cur = out[key]
            if (record["revision"] > cur["revision"]) or (
                record["revision"] == cur["revision"] and record["observed"] > cur["observed"]
            ):
                out[key] = record
    return [dict(out[key]) for key in sorted(out)]

