def normalize_tags(tags):
    result = []
    seen = set()
    for tag in tags:
        if not isinstance(tag, str):
            raise ValueError("tag is not a string")
        trimmed = tag.strip()
        if not trimmed:
            raise ValueError("tag is empty after trimming")
        folded = trimmed.casefold()
        if folded not in seen:
            seen.add(folded)
            result.append(trimmed)
    return result

