def normalize_tags(tags):
    seen = {}
    result = []
    for tag in tags:
        stripped = tag.strip()
        if not stripped:
            raise ValueError("empty tag")
        key = stripped.casefold()
        if key not in seen:
            seen[key] = True
            result.append(stripped)
    return result
